class Command(BaseCommand):
    help = "E資格の初期カードを登録します"

    @transaction.atomic
    def handle(self, *args, **options):
        created = 0
        updated = 0
        for front, back, category, topic, trap, chapter in CARDS:
            _, was_created = Card.objects.update_or_create(front=front, defaults={
                "back": back, "category": category, "topic": topic, "trap": trap, "chapter": chapter
            })
            created += int(was_created)
            updated += int(not was_created)
        self.stdout.write(self.style.SUCCESS(f"{created}件追加、{updated}件更新しました"))
